# The OTA bench build (docs/ota_bench.md): talks to ota_bench_server.py on the
# local network, with the bench's test key and CA, never the production ones.
# Reads bench/ (generated by `python ota_bench_server.py init`, not committed).
#
#   OTA_BENCH_TAG=b pio run -e waveshare_photopainter_73e6_ota1_bench
#       a second image of the same commit (a different hash)
#   OTA_BENCH_FAULT=crash_pending | hang_pending | reset_before_select | reset_after_select
#       an image that fails on purpose, for the rollback cases
import json
import os
import pathlib

Import("env")  # noqa: F821

FAULTS = {
    "crash_pending": "WIGNET_OTA_BENCH_CRASH_PENDING",
    "hang_pending": "WIGNET_OTA_BENCH_HANG_PENDING",
    "reset_before_select": "WIGNET_OTA_BENCH_RESET_BEFORE_SELECT",
    "reset_after_select": "WIGNET_OTA_BENCH_RESET_AFTER_SELECT",
}

bench = pathlib.Path(env["PROJECT_DIR"]) / "bench"  # noqa: F821
config = bench / "bench.json"
if not config.exists() or not (bench / "ota_bench.h").exists():
    raise SystemExit("bench/ is missing: run `python ota_bench_server.py init --ip <this computer's LAN IP>` first")
settings = json.loads(config.read_text())

tag = os.environ.get("OTA_BENCH_TAG", "a")
fault = os.environ.get("OTA_BENCH_FAULT", "")
if fault and fault not in FAULTS:
    raise SystemExit(f"OTA_BENCH_FAULT={fault}: expected one of {', '.join(FAULTS)}")

env.Append(  # noqa: F821
    CPPPATH=[str(bench)],
    CPPDEFINES=[
        "WIGNET_OTA_BENCH",
        ("WIGNET_BENCH_HOST", env.StringifyMacro(settings["ip"])),  # noqa: F821
        ("WIGNET_BENCH_PORT", settings["port"]),
        ("WIGNET_OTA_BENCH_TAG", env.StringifyMacro(tag + (f"+{fault}" if fault else ""))),  # noqa: F821
    ]
    + ([FAULTS[fault]] if fault else []),
)
print(f"OTA bench build: server {settings['ip']}:{settings['port']}, tag {tag}" + (f", fault {fault}" if fault else ""))
